    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # label components of each non-bg color (4-conn), same color only
    seen=[[False]*W for _ in range(H)]
    reach=[[False]*W for _ in range(H)]
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==bg and not reach[i][j]: reach[i][j]=True; q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==bg and not reach[i][j]: reach[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and g[a][b]==bg and not reach[a][b]:
                reach[a][b]=True; q.append((a,b))
    # components
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; comp=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=y<W and g[x][y]==c and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[a for a,_ in comp]; cs=[b for _,b in comp]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                fill=2 if (h==4 and w==4) else 7
                for a in range(min(rs),max(rs)+1):
                    for b in range(min(cs),max(cs)+1):
                        if g[a][b]==bg and not reach[a][b]:
                            g[a][b]=fill
    return g

